/* Shared status definitions, database configuration and deterministic resolution. */
(function(g){'use strict';const need=(v,s)=>{if(!v)throw Error(s);},copy=x=>JSON.parse(JSON.stringify(x));
const types={poison:['Poison','พิษ','☠'],burn:['Burn','เผาไหม้','🔥'],frozen:['Frozen','แช่แข็ง','❄'],stun:['Stun','สตัน','✦'],slow:['Slow','เชื่องช้า','◷'],broken:['Defense Down','เกราะลด','▣'],weaken:['Attack Down','โจมตีลด','↘'],blind:['Blind','ตาบอด','◉'],silence:['Silence','ใบ้','…'],taunt:['Taunt','ยั่วยุ','!']};
const fields=[{key:'battleStatus',label:'สถานะหลังโจมตีโดน',type:'select',options:['legacy','none',...Object.keys(types)],optionLabels:{legacy:'ใช้สถานะเดิม / statusEffects',none:'ไม่ใส่สถานะ',...Object.fromEntries(Object.entries(types).map(([k,v])=>[k,v[1]]))},default:'legacy',hint:'ใช้กับท่าโจมตีที่เชื่อมแล้ว สถานะจะตรวจหลังโจมตีโดนและเป้าหมายยังมีชีวิต'},{key:'statusChance',label:'โอกาสติดสถานะ (%)',type:'number',default:100},{key:'statusTurns',label:'ระยะเวลาสถานะ (เทิร์นเป้าหมาย)',type:'number',default:2},{key:'statusDamage',label:'ความเสียหายพิษ / เผาไหม้ต่อเทิร์น',type:'number',default:3,hint:'เป็นความเสียหายตรง ไม่คิดเกราะ ไม่ทอยคริติคอล'},{key:'statusSaveStat',label:'ค่าสำหรับทอยต้านสถานะ',type:'select',options:['CON','STR','DEX','INT','WIS','CHA'],default:'CON',hint:'ใช้ saveDC เดิม: 0 ไม่ทอย มิฉะนั้น d20 + modifier ของเป้าหมาย ≥ DC จะต้านสถานะได้ ดาเมจโจมตียังเท่าเดิม'}].map(f=>({...f,group:'statuses'}));
if(g.EvervaleContentSchema)for(const kind of ['skill','spell'])for(const f of fields)g.EvervaleContentSchema.schemas[kind].fields.push({...f});
const aliases={Poison:'poison',Burn:'burn',Frozen:'frozen',Stun:'stun',Slow:'slow','Defense Down':'broken',Broken:'broken','Attack Down':'weaken',Weaken:'weaken',Blind:'blind',Blinded:'blind',Silence:'silence',Taunt:'taunt'};
function validate(v){need(v&&Array.isArray(v.kinds)&&v.kinds.length<=10&&new Set(v.kinds).size===v.kinds.length&&v.kinds.every(k=>types[k]),'สถานะนี้ยังไม่รองรับ');need(Number.isFinite(v.chance)&&v.chance>=0&&v.chance<=100&&Number.isInteger(v.turns)&&v.turns>=1&&v.turns<=20&&Number.isInteger(v.damage)&&v.damage>=0&&v.damage<=999&&Number.isInteger(v.dc)&&v.dc>=0&&v.dc<=40&&['CON','STR','DEX','INT','WIS','CHA'].includes(v.stat),'สถานะ: โอกาส 0–100 ระยะเวลา 1–20 ดาเมจ 0–999 และ DC 0–40');return v;}
function fromRecord(r,fallback=[]){const mode=r.battleStatus??'legacy';need(mode==='legacy'||mode==='none'||types[mode],'ชนิดสถานะไม่ถูกต้อง');const tags=r.statusEffects||[];need(Array.isArray(tags),'statusEffects ต้องเป็นรายการ');const kinds=mode==='none'?[]:mode==='legacy'?(tags.length?tags.map(t=>aliases[t]):fallback):[mode];return validate({kinds:[...new Set(kinds)],chance:r.statusChance??100,turns:r.statusTurns??(kinds.includes('frozen')||kinds.includes('stun')?1:2),damage:r.statusDamage??3,dc:r.saveDC??0,stat:r.statusSaveStat??'CON'});}
function random(e){let x=e.seed>>>0;x^=x<<13;x^=x>>>17;x^=x<<5;e.seed=x>>>0;return e.seed/4294967296;}
function note(e,s){e.log.unshift(s);e.log=e.log.slice(0,30);}
function immune(t,k){const tags=[types[k][0],k,...(k==='broken'?['Broken']:k==='weaken'?['Weaken']:k==='blind'?['Blinded']:[])].map(x=>x.toLowerCase());return (t.immunities||[]).some(x=>tags.includes(String(x).trim().toLowerCase()))||k==='poison'&&t.effects.antidote>0;}
function apply(e,t,k,turns,damage){need(types[k]&&Number.isInteger(turns)&&turns>0&&turns<=10000&&(damage===undefined||Number.isInteger(damage)&&damage>=0&&damage<=999),'สถานะหรือระยะเวลาไม่ถูกต้อง');if(t.hp<=0)return false;if(immune(t,k)){note(e,t.name+' • ภูมิคุ้มกันสถานะ '+types[k][0]);return false;}t.effects[k]=Math.max(t.effects[k]||0,turns);t.statusMeta=t.statusMeta||{};const meta=t.statusMeta[k]||{};if(damage!==undefined)meta.damage=Math.max(meta.damage||0,damage);if(t.side==='player'&&e.detectPhase==='enemy')meta.skipRound=Math.max(meta.skipRound||0,e.round+1);t.statusMeta[k]=meta;if(['stun','frozen','silence'].includes(k)&&t.casting){delete t.casting;note(e,t.name+' ถูกขัดจังหวะการร่าย');}note(e,t.name+' • '+types[k][1]+' '+t.effects[k]+' เทิร์น');return true;}
function resolve(e,source,target,v){validate(v);if(!target.hp)return;for(const k of v.kinds){if(immune(target,k)){note(e,target.name+' • ภูมิคุ้มกันสถานะ '+types[k][0]);continue;}if(v.chance<=0||v.chance<100&&random(e)*100>=v.chance){note(e,target.name+' • ไม่ติด'+types[k][1]);continue;}if(v.dc){const X=g.DecideCharacterCombat||(typeof require==='function'?require('./character-combat.js'):null),stat=target.side==='enemy'&&target.monsterCombat?target.monsterCombat.stats[v.stat]:X.amount(target,v.stat),die=1+Math.floor(random(e)*20),total=die+Math.floor((stat-10)/2);note(e,target.name+' ต้าน '+types[k][1]+' • d20='+die+' รวม '+total+' / DC '+v.dc);if(total>=v.dc)continue;}if(apply(e,target,k,v.turns,['poison','burn'].includes(k)?v.damage:undefined)&&k==='taunt')target.taunt=source.id;}}
function clear(t,k){t.effects[k]=0;if(t.statusMeta)delete t.statusMeta[k];if(k==='poison')delete t.poisonDamage;if(k==='taunt')delete t.taunt;}
function blocked(u){return !!(u?.effects?.stun||u?.effects?.frozen);}
function describeConfig(v){return v?.kinds.length?v.kinds.map(k=>types[k][1]).join(' / ')+' '+v.turns+' เทิร์น · '+v.chance+'%'+(v.kinds.some(k=>['poison','burn'].includes(k))?' · '+v.damage+' HP/เทิร์น':'')+(v.dc?' · '+v.stat+' DC '+v.dc:''):'';}
function describe(u){return Object.entries(types).filter(([k])=>u.effects?.[k]>0).map(([k,v])=>v[2]+' '+v[1]+' '+u.effects[k]+' เทิร์น').join(' • ');}
function prepare(e,rows){if(e.design!==1||e.statusSkills!==undefined)return;e.statusSkills={};const N=g.DecideCreation||(typeof require==='function'?require('./creation-data.js'):null);for(const id of new Set(e.units.filter(u=>u.side==='player').flatMap(u=>u.skills||[]))){const r=rows.find(r=>r.kind==='skill'&&r.id==='decide-'+id);if(r&&r.enabled!==false&&fields.some(f=>r[f.key]!==undefined)&&N.skills[id]?.power>0)e.statusSkills[id]=copy(fromRecord(r,({poison:['poison'],frost:['slow'],break:['broken'],acid:['broken']}[id]||[])));}}
function validateEncounter(e){if(e.statusSkills!==undefined){need(e.statusSkills&&typeof e.statusSkills==='object'&&!Array.isArray(e.statusSkills)&&Object.keys(e.statusSkills).length<=30,'ข้อมูลสถานะสกิลผิด');const N=g.DecideCreation||(typeof require==='function'?require('./creation-data.js'):null);for(const [id,v]of Object.entries(e.statusSkills)){need(N.skills[id]?.power>0,'สกิลนี้ไม่รองรับสถานะหลังโจมตี');validate(v);}}for(const u of e.units)if(u.statusMeta!==undefined){need(u.statusMeta&&typeof u.statusMeta==='object'&&!Array.isArray(u.statusMeta)&&Object.keys(u.statusMeta).length<=10,'ข้อมูลสถานะผิด');for(const [k,v]of Object.entries(u.statusMeta))need(types[k]&&v&&typeof v==='object'&&(v.damage===undefined||Number.isInteger(v.damage)&&v.damage>=0&&v.damage<=999)&&(v.skipRound===undefined||Number.isInteger(v.skipRound)&&v.skipRound>=1&&v.skipRound<=e.round+1),'ข้อมูลระยะเวลาสถานะผิด');}}
const api={types,fields,validate,fromRecord,immune,apply,resolve,clear,blocked,describe,describeConfig,prepare,validateEncounter};g.DecideStatusEffects=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
